// SPDX-License-Identifier: GPL-3.0-only
//! **V&V: `petir::integration::{glfixed_table_alloc, glfixed, glfixed_point}`
//! against compiled GSL 2.8** (gh:#1340). Methodology, reference and
//! prediction P3: `verification_and_validation/integration_family_gh1340.md`.
//!
//! Replays `reference-data/gsl/glfixed-gsl-2.8-reference.txt` (driver
//! `glfixed_reference_driver.c`): 40 table sizes (27 precomputed, 13
//! generated by Newton's method from a `cos` start), 4 integrands on 2
//! intervals per size, and `glfixed_point` for every point of the small
//! tables. Table entries of the precomputed sizes must be bit-identical (they
//! are copied from the C file by script); generated entries are counted
//! bit-identical and the counts pinned (see the assertion's comment for the
//! measured numbers and the demonstrated cause).

use petir::integration::{glfixed, glfixed_point, glfixed_table_alloc};
use petir::PetirError;
use std::collections::HashMap;

const REFERENCE: &str = include_str!("../../../reference-data/gsl/glfixed-gsl-2.8-reference.txt");

fn ulps(a: f64, b: f64) -> u64 {
    if a.to_bits() == b.to_bits() {
        return 0;
    }
    let (ia, ib) = (a.to_bits() as i64, b.to_bits() as i64);
    ia.abs_diff(ib)
}

fn integrand(name: &str) -> fn(f64) -> f64 {
    match name {
        "poly" => |x| x * x * x * x * x - 2.0 * x + 1.0,
        "exp" => |x| x.exp(),
        "cos7" => |x| (7.0 * x).cos(),
        "rational" => |x| 1.0 / (1.0 + 25.0 * x * x),
        other => panic!("unknown integrand {other}"),
    }
}

#[test]
fn glfixed_matches_compiled_gsl() {
    let mut tables: HashMap<usize, petir::integration::GlFixedTable> = HashMap::new();
    // (entries, bit-identical, max ulps) for precomputed and generated.
    let mut pre = (0usize, 0usize, 0u64);
    let mut gen = (0usize, 0usize, 0u64);
    let (mut ints, mut ints_exact, mut ints_max_ulp) = (0usize, 0usize, 0u64);
    let (mut pts, mut pts_exact, mut pts_max_ulp) = (0usize, 0usize, 0u64);
    let mut pterr = 0usize;
    let mut gen_tables = 0usize;

    for line in REFERENCE.lines() {
        let f: Vec<&str> = line.split_whitespace().collect();
        match f.first().copied() {
            Some("TBL") => {
                let n: usize = f[1].parse().unwrap();
                let precomputed = f[2] == "1";
                let m: usize = f[3].parse().unwrap();
                let vals: Vec<f64> = f[4..].iter().map(|s| s.parse().unwrap()).collect();
                assert_eq!(vals.len(), 2 * m, "n={n}");
                let t = glfixed_table_alloc(n).unwrap();
                assert_eq!(t.is_precomputed(), precomputed, "n={n} precomputed flag");
                assert_eq!(t.abscissae().len(), m);
                assert_eq!(t.weights().len(), m);
                let acc = if precomputed {
                    &mut pre
                } else {
                    gen_tables += 1;
                    &mut gen
                };
                let ours = t.abscissae().iter().chain(t.weights().iter());
                for (k, (a, b)) in ours.zip(vals.iter()).enumerate() {
                    let u = ulps(*a, *b);
                    if u > 1 {
                        println!("  n={n} entry {k} (m={m}): {a:e} vs GSL {b:e} ({u} ulp)");
                    }
                    acc.0 += 1;
                    if u == 0 {
                        acc.1 += 1;
                    }
                    acc.2 = acc.2.max(u);
                }
                tables.insert(n, t);
            }
            Some("INT") => {
                let n: usize = f[1].parse().unwrap();
                let g = integrand(f[2]);
                let (a, b): (f64, f64) = (f[3].parse().unwrap(), f[4].parse().unwrap());
                let want: f64 = f[5].parse().unwrap();
                let t = tables.get(&n).unwrap();
                let got = glfixed(g, a, b, t);
                let u = ulps(got, want);
                ints += 1;
                if u == 0 {
                    ints_exact += 1;
                }
                ints_max_ulp = ints_max_ulp.max(u);
            }
            Some("PT") => {
                let n: usize = f[1].parse().unwrap();
                let (a, b): (f64, f64) = (f[2].parse().unwrap(), f[3].parse().unwrap());
                let i: usize = f[4].parse().unwrap();
                let st: i32 = f[5].parse().unwrap();
                let (xw, ww): (f64, f64) = (f[6].parse().unwrap(), f[7].parse().unwrap());
                assert_eq!(st, 0);
                let t = tables.get(&n).unwrap();
                let (xi, wi) = glfixed_point(a, b, i, t).unwrap();
                pts += 2;
                for (g, w) in [(xi, xw), (wi, ww)] {
                    let u = ulps(g, w);
                    if u == 0 {
                        pts_exact += 1;
                    }
                    pts_max_ulp = pts_max_ulp.max(u);
                }
            }
            Some("PTERR") => {
                let n: usize = f[1].parse().unwrap();
                let st: i32 = f[2].parse().unwrap();
                assert_eq!(st, 4, "GSL_EINVAL for i = n");
                let t = tables.get(&n).unwrap();
                assert_eq!(glfixed_point(0.0, 1.0, n, t), Err(PetirError::Invalid));
                pterr += 1;
            }
            _ => {}
        }
    }
    println!(
        "  glfixed vs GSL 2.8: precomputed entries {}/{} bit-identical (max {} ulp); \
         generated ({gen_tables} tables) {}/{} (max {} ulp); integrals {ints_exact}/{ints} \
         (max {ints_max_ulp} ulp); points {pts_exact}/{pts} (max {pts_max_ulp} ulp); \
         EINVAL rows {pterr}",
        pre.1, pre.0, pre.2, gen.1, gen.0, gen.2
    );
    assert_eq!(tables.len(), 40);
    assert_eq!(gen_tables, 13);
    assert_eq!(pre.1, pre.0, "precomputed tables are bit-identical");
    assert_eq!(pterr, 40);
    // Pinned (measured 2026-11-13; the prediction of <= 1 ulp FAILED, see the
    // V&V record). Only the 13 GENERATED tables differ, and only in weights of
    // the large ones (n >= 513, ~1e-3 in size, relative 1e-14): the Newton
    // start is `cos(pi (4i-1) / (4n+2)) * t0`, and glibc's `cos` and PETIR's
    // differ in the last bit for some arguments. DEMONSTRATED: GSL's driver
    // relinked with PETIR's `cos` alone (a diagnostic shim, not committed)
    // makes the generated tables 5086/5086 and the points 2808/2808
    // bit-identical to PETIR's. Accepted per AGENTS.md; counts pinned.
    assert_eq!((gen.0, gen.1, gen.2), (5086, 5031, 224));
    assert_eq!((ints, ints_exact, ints_max_ulp), (320, 309, 22));
    assert_eq!((pts, pts_exact, pts_max_ulp), (2808, 2786, 88));
}
